export interface Customer {
  yearsWithMHPCO: number;
}

export interface Item {
  type: string;
  material?: string;
  enchantment?: number;
  cursed?: boolean;
}

const PROCESSING_FEE = 5;
const SWORD_BASE_PREMIUM = 100;
const FIRST_INSURANCE_SURCHARGE_RATE = 0.1;

/** Premium for a single insured item: its base premium plus the
 *  item-specific first-insurance surcharge. */
function itemPremium(item: Item): number {
  const base = SWORD_BASE_PREMIUM;
  return base + base * FIRST_INSURANCE_SURCHARGE_RATE;
}

export function quote(customer: Customer, items: Item[], previousContracts: number): number {
  const policyPremium = items.reduce((sum, item) => sum + itemPremium(item), 0);
  return policyPremium + PROCESSING_FEE;
}
