export interface Customer {
  yearsWithMHPCO: number;
}

export interface Item {
  type: string;
  material?: string;
  enchantment?: number;
  cursed?: boolean;
}

/** Every component -- rune, moonstone -- carries the same price-list base
 *  premium, independent of which component it is. */
const COMPONENT_BASE_PREMIUM = 25;

/** MHPCO price list: base premium in G per item type. */
const BASE_PREMIUMS: Record<string, number> = {
  sword: 100,
  amulet: 60,
  staff: 80,
  potion: 40,
  rune: COMPONENT_BASE_PREMIUM,
  moonstone: COMPONENT_BASE_PREMIUM,
};

const FIRST_INSURANCE_SURCHARGE_RATE = 0.1;
const PROCESSING_FEE = 5;

/** The MHPCO price list's base premium for an insured item. */
function basePremium(item: Item): number {
  return BASE_PREMIUMS[item.type];
}

/** An item's premium: its price-list base premium plus the item-specific
 *  modifiers that attach to that item alone. Every item in a quote is
 *  treated as a first insurance and carries the initial assessment
 *  surcharge, regardless of customer history. */
function itemPremium(item: Item): number {
  const base = basePremium(item);
  return base + base * FIRST_INSURANCE_SURCHARGE_RATE;
}

/** The policy base premium: the sum of the individual item premiums, to
 *  which policy-wide modifiers attach. */
function policyPremium(items: Item[]): number {
  return items.reduce((sum, item) => sum + itemPremium(item), 0);
}

export function quote(customer: Customer, items: Item[], previousContracts: number): number {
  return policyPremium(items) + PROCESSING_FEE;
}

