export interface Damage {
  itemType: string;
  amount: number;
}

export interface Incident {
  cause: string;
  damages: Damage[];
}

export interface Policy {
  items: Item[];
}

export interface ClaimResult {
  payout: number;
  remainingCap: number;
}

const DEDUCTIBLE_PER_DAMAGE = 100;

/** The MHPCO opens a policy over the items a quote covered. */
export function createPolicy(items: Item[]): Policy {
  return { items };
}

/** The reimbursement for one damage event, after the deductible the
 *  MHPCO applies to every damage event. */
function damagePayout(damage: Damage): number {
  return damage.amount - DEDUCTIBLE_PER_DAMAGE;
}

export function claim(policy: Policy, incident: Incident): ClaimResult {
  const payout = incident.damages.reduce((sum, damage) => sum + damagePayout(damage), 0);
  return { payout, remainingCap: 0 };
}
EOF
