/** The claims office: what the MHPCO pays out when an insured item is damaged.
 *  Every decision here belongs to the claims handbook -- the deductible, the
 *  special clauses, the cap on a policy -- and is revised independently of the
 *  tariff that priced the policy. */

import { type Item } from "./item-catalog.js";

export interface Damage {
  itemType: string;
  amount: number;
}

export interface Incident {
  cause: string;
  damages: Damage[];
}

export interface Policy {
  items: Item[];
}

export interface ClaimResult {
  payout: number;
  remainingCap: number;
}

const DEDUCTIBLE_PER_DAMAGE = 100;

/** The MHPCO opens a policy over the items a quote covered. */
export function createPolicy(items: Item[]): Policy {
  return { items };
}

/** The MHPCO bears its deductible against a damage; it never turns the
 *  deductible round into a charge the customer owes the office. A damage
 *  smaller than the deductible is simply not reimbursed. */
function neverACharge(reimbursement: number): number {
  return Math.max(reimbursement, 0);
}

/** The handbook's reimbursement decision for one damage event: the MHPCO keeps
 *  back its deductible from the reimbursable amount. The office has not yet
 *  ruled here on the special clauses that read the damaged item (high
 *  enchantment, dragon material), so the reimbursable amount is currently the
 *  reported damage itself. */
function reimbursementForDamage(damage: Damage): number {
  return neverACharge(damage.amount - DEDUCTIBLE_PER_DAMAGE);
}

/** What the MHPCO settles for one incident against a policy: every reported
 *  damage reimbursed under the handbook, added up. The cap the office keeps on
 *  a policy is a separate decision it has not yet made, so the remaining cap is
 *  reported as nothing held back. */
export function claim(policy: Policy, incident: Incident): ClaimResult {
  const payout = incident.damages.reduce(
    (sum, damage) => sum + reimbursementForDamage(damage),
    0,
  );
  return { payout, remainingCap: 0 };
}

