cat > src/cli.ts <<'EOF'
#!/usr/bin/env node
/** The MHPCO's counter clerk: reads a scenario from stdin, walks its steps in
 *  order past the premium and claims offices, and writes the results to
 *  stdout. Transport and JSON translation live here; no office rule does. */

import { readFileSync } from "node:fs";
import {
  claim,
  createPolicy,
  quote,
  type Customer,
  type Incident,
  type Item,
  type Policy,
} from "./claim-office.js";

interface QuoteStep {
  op: "quote";
  items: Item[];
}

interface ClaimStep {
  op: "claim";
  policy: number;
  incident: Incident;
}

type Step = QuoteStep | ClaimStep;

interface Scenario {
  customer: Customer;
  steps: Step[];
}

type StepResult = { premium: number } | { payout: number; remainingCap: number };

/** The policy a claim step names by the zero-based index of the quote step
 *  that created it. */
function namedPolicy(policies: Map<number, Policy>, step: ClaimStep): Policy {
  const policy = policies.get(step.policy);
  if (policy === undefined) {
    throw new Error(`step ${step.policy} did not create a policy to claim against`);
  }
  return policy;
}

function settleScenario(scenario: Scenario): StepResult[] {
  const policies = new Map<number, Policy>();
  return scenario.steps.map((step, index) => {
    if (step.op === "claim") {
      return claim(namedPolicy(policies, step), step.incident);
    }
    const premium = quote(scenario.customer, step.items, policies.size);
    policies.set(index, createPolicy(step.items));
    return { premium };
  });
}

function main(): void {
  const scenario = JSON.parse(readFileSync(0, "utf8")) as Scenario;
  process.stdout.write(JSON.stringify({ results: settleScenario(scenario) }));
}

try {
  main();
} catch (error) {
  process.stderr.write(`${error instanceof Error ? error.message : String(error)}\n`);
  process.exitCode = 1;
}
EOF
